const raw = String($json.event_json || '').trim();
let event;
try { event = JSON.parse(raw); } catch { throw new Error('invalid_shopify_order_event_json'); }
const uuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
if (!uuid.test(String(event.event_id || ''))) throw new Error('invalid_event_id');
if (event.event_type !== 'shopify.order.processed') throw new Error('unsupported_event_type');
if (event.schema_version !== 1) throw new Error('unsupported_schema_version');
if (event.owner_id !== null && event.owner_id !== undefined) throw new Error('order_event_owner_must_be_null');
if (!event.aggregate || event.aggregate.type !== 'ORDER' || !uuid.test(String(event.aggregate.id || ''))) throw new Error('invalid_order_aggregate');
if (!event.payload || !uuid.test(String(event.payload.order_id || ''))) throw new Error('invalid_order_payload');
if (String(event.aggregate.id) !== String(event.payload.order_id)) throw new Error('aggregate_order_mismatch');
if (event.payload.status !== 'PAID') throw new Error('invalid_order_status');
if (!String(event.payload.source_reference || '').trim()) throw new Error('missing_shopify_source_reference');
if (!Number.isInteger(event.payload.item_count) || event.payload.item_count < 1 || event.payload.item_count > 1000) throw new Error('invalid_order_item_count');
const expectedKey = `shopify.order.processed:${event.payload.order_id}:v1`;
if (String(event.idempotency_key || '') !== expectedKey) throw new Error('invalid_idempotency_key');
return [{json:{event}}];

const crypto = require('crypto');
const event = $json.event;
const secret = String($env.DROP_RATE_AUTOMATION_COMMAND_SECRET || '').trim();
const receiptUrl = String($env.DROP_RATE_API_AUTOMATION_CONTROL_URL || '').trim();
if (secret.length < 32) throw new Error('automation_command_secret_not_configured');
if (!/\/automation\/control\/receipt$/.test(receiptUrl)) throw new Error('automation_control_receipt_url_invalid');
const body = JSON.stringify(event);
const timestamp = String(Math.floor(Date.now()/1000));
const signature = 'sha256=' + crypto.createHmac('sha256', secret).update(timestamp + '.' + body, 'utf8').digest('hex');
const commandUrl = receiptUrl.replace(/\/automation\/control\/receipt$/, '/automation/commands/shopify/order-processed');
return [{json:{command_url:commandUrl,command_body:body,command_timestamp:timestamp,command_signature:signature}}];

const response = $input.first().json || {};
const statusCode = Number(response.statusCode || 0);
if (statusCode < 200 || statusCode >= 300) throw new Error('shopify_order_verification_http_' + statusCode);
const body = response.body || {};
const expectedOrderId = String($('Normalize Committed Order Event').item.json.event.payload.order_id || '');
if (body.status !== 'VERIFIED' || String(body.order_id || '') !== expectedOrderId) throw new Error('shopify_order_not_verified');
return [{json:{verified:true,result:body}}];
